async function enterEditor(page){if(await page.locator('#firstVisit').isVisible())await page.locator('[data-skip]').click();if(await page.locator('#workspaceHome').isVisible())await page.locator('#continueWriting').click()}
async function menu(page,name,action){await enterEditor(page);if(name==='File'){
 await page.locator('#backstageToggle').click();const section=['encryptedBackup','end','recovery','privacy'].includes(action)?'Session':['deviceStorage','appearance','appStatus'].includes(action)?'Settings':null;if(section)await page.locator('[data-home-page="'+section+'"]').click();await page.locator('[data-home-action="'+action+'"]').click();
 }else{const tab=action==='pagePreview'?'Layout':{Edit:'Home',Format:'Home',View:'View',Insert:'Insert',Review:'Review',Tools:'Tools'}[name]||name;await page.locator('[role="tab"]').filter({hasText:new RegExp('^'+tab+'$')}).click();await page.locator('.ribbon-panel:not([hidden]) [data-menu-action="'+action+'"]').click()}}
async function start(page){await page.goto('./');await expect(page.locator('#document-content')).toBeAttached();await enterEditor(page)}
async function write(page){await page.locator('#title').fill('Release smoke document');await page.locator('#document-content').fill('An independent backup keeps this document safe.');await menu(page,'File','saveNow');await expect(page.locator('#saveState')).toHaveText('Saved on this device');await expect(page.locator('#toast')).toHaveText('Workspace saved on this device.')}
async function download(page,testInfo,extension){const link=page.locator('.download-link[download$=".'+extension+'"]');await expect(link).toBeVisible();const event=page.waitForEvent('download');await link.click();const result=await event,file=testInfo.outputPath(result.suggestedFilename());await result.saveAs(file);expect(await result.failure()).toBeNull();return file}
async function open(page,file){await menu(page,'File','import');await page.locator('#nativeFileInput').setInputFiles(file)}

test.beforeEach(async({page,context})=>{const errors=[],external=[];page.on('pageerror',error=>errors.push(error.stack||error.message));context.on('request',request=>{const url=new URL(request.url());if(['http:','https:'].includes(url.protocol)&&url.origin!=='http://127.0.0.1:4173')external.push(url.origin)});page.__releaseErrors=errors;page.__externalRequests=external});
test.afterEach(async({page})=>{expect(page.__releaseErrors).toEqual([]);expect(page.__externalRequests).toEqual([])});

test('write, reload, download HTML and reopen the exact downloaded file',async({page},testInfo)=>{
 await start(page);await write(page);await page.reload();await expect(page.locator('#title')).toHaveValue('Release smoke document');await expect(page.locator('#document-content')).toContainText('An independent backup keeps this document safe.');
 await menu(page,'File','export');await page.locator('#htmlExport').click();const file=await download(page,testInfo,'html');expect(await fs.readFile(file,'utf8')).toContain('An independent backup keeps this document safe.');await page.locator('#closeDialog').click();await open(page,file);await expect(page.locator('#docCount')).toHaveText('2');await expect(page.locator('#document-content')).toContainText('An independent backup keeps this document safe.');
 expect(await page.evaluate(()=>document.documentElement.scrollWidth<=innerWidth+2)).toBe(true);
});

test('complete ZIP retains an actually rendered PDF field through download and restore',async({page},testInfo)=>{
 await start(page);await write(page);await menu(page,'Tools','pdfTools');await page.locator('#pdfNew').click();await expect(page.locator('#pdfPage canvas')).toBeVisible();await expect(page.locator('#pdfStatus')).toContainText('Saved edits');await page.locator('#pdfMode').selectOption('field-text');await page.locator('#pdfFieldName').fill('Release field');await page.locator('#pdfText').fill('Stored value');await page.locator('#pdfPage').click({position:{x:100,y:100}});await expect(page.locator('[data-pdf-field="Release field"]')).toHaveValue('Stored value');await page.locator('#pdfSave').click();const pdfFile=await download(page,testInfo,'pdf'),pdf=await loadPDF(new Uint8Array(await fs.readFile(pdfFile)));expect(describeFields(pdf).find(field=>field.name==='Release field')?.value).toBe('Stored value');await page.locator('#closeDialog').click();
 await menu(page,'File','backup');const file=await download(page,testInfo,'zip'),backup=readWorkspaceBackup(new Uint8Array(await fs.readFile(file)));expect(backup.pdfs).toHaveLength(1);await open(page,file);await expect(page.locator('#docCount')).toHaveText('2');await menu(page,'Tools','pdfTools');await expect(page.locator('#pdfSaved option')).toHaveCount(3);const last=await page.locator('#pdfSaved option').last().getAttribute('value');await page.locator('#pdfSaved').selectOption(last);await expect(page.locator('[data-pdf-field="Release field"]')).toHaveValue('Stored value');
});

test('encrypted backup rejects a wrong password and restores the exact downloaded file',async({page},testInfo)=>{
 await start(page);await write(page);await menu(page,'File','encryptedBackup');await page.locator('#backupPassword').fill('fixture-backup-password');await page.locator('#backupConfirm').fill('fixture-backup-password');await page.locator('#encryptWorkspace').click();const file=await download(page,testInfo,'sfbackup');await page.locator('#closeDialog').click();await open(page,file);await page.locator('#unlockBackupPassword').fill('wrong-password');await page.locator('#unlockBackup').click();await expect(page.locator('#unlockBackupStatus')).not.toHaveText('Unlocking…');await expect(page.locator('#docCount')).toHaveText('1');await page.locator('#unlockBackupPassword').fill('fixture-backup-password');await page.locator('#unlockBackup').click();await expect(page.locator('#docCount')).toHaveText('2');await expect(page.locator('#document-content')).toContainText('An independent backup keeps this document safe.');
});

test('project-path PWA reopens offline and recognizes a local OCR scan after preparation',async({page,context})=>{
 await start(page);await write(page);await page.evaluate(()=>navigator.serviceWorker.ready);await page.waitForFunction(()=>!!navigator.serviceWorker.controller);await menu(page,'Tools','offlineTools');await expect(page.locator('#prepareOfflineButton')).toBeEnabled();await page.locator('#prepareOfflineButton').click();await expect(page.locator('#offlinePreparationStatus')).toContainText('ready offline',{timeout:60000});await page.locator('#closeDialog').click();await context.setOffline(true);await page.reload();await expect(page.locator('#document-content')).toContainText('An independent backup keeps this document safe.');await menu(page,'Tools','ocrTools');await page.locator('#ocrLanguage').selectOption('fra');await page.locator('#ocrFile').setInputFiles('test/fixtures/ocr-french.png');await expect(page.locator('#ocrStatus')).toContainText('Adjust the crop');await page.locator('#ocrRun').click();await expect(page.locator('#ocrStatus')).toContainText('Recognition complete',{timeout:60000});await expect(page.locator('#ocrResult')).toHaveValue(/Bonjour café/);await page.locator('#ocrInsert').click();await expect(page.locator('#document-content')).toContainText('Bonjour café');
});

test('long page-bottom notes continue without losing text or overlapping the body',async({page},testInfo)=>{
 await start(page);const note=('A long note retains its café and 😀 characters across page boundaries. '.repeat(55)).slice(0,3900),file=testInfo.outputPath('long-note.html');await fs.writeFile(file,exportHTMLDocument('<p>A reference<sup data-forge-footnote="true" data-note-text="'+encodeURIComponent(note)+'">1</sup></p>','Long note',{notePlacement:'page'}));await open(page,file);await expect(page.locator('#title')).toHaveValue('Long note');await menu(page,'View','pagePreview');await expect(page.locator('#printMeasuredPages')).toBeEnabled();expect(await page.locator('.preview-page-notes .note-fragment').count()).toBeGreaterThan(1);
 const geometry=await page.locator('.preview-page').evaluateAll(pages=>pages.map(sheet=>{const body=sheet.querySelector('.preview-body'),notes=sheet.querySelector('.preview-page-notes');return {bodyBottom:body.getBoundingClientRect().bottom,noteTop:notes?.getBoundingClientRect().top,hasText:!!body.textContent.trim()}}));for(const item of geometry)if(item.hasText&&item.noteTop!==undefined)expect(item.bodyBottom).toBeLessThanOrEqual(item.noteTop+2);expect((await page.locator('.preview-page-notes .note-fragment').allTextContents()).join('')).toBe(note);await page.locator('#closeDialog').click();await menu(page,'View','pagedEditing');await expect(page.locator('.live-edit-footnotes [data-note-continued="true"]').first()).toBeAttached();expect((await page.locator('.live-edit-footnotes .note-fragment').allTextContents()).join('')).toBe(note);
});
test('custom image contour can be edited, downloaded and reopened with its wrapping',async({page},testInfo)=>{
 await start(page);const png='data:image/png;base64,'+(await fs.readFile('test/fixtures/ocr-french.png')).toString('base64'),file=testInfo.outputPath('contour.html');await fs.writeFile(file,exportHTMLDocument('<img src="'+png+'" data-image-width="40"><p>Text follows the image contour. '+'</p>','Contour',{}));await open(page,file);await page.locator('#document-content img').click();await page.locator('#objectDesign').click();await page.locator('#imageShape').selectOption('polygon');await page.locator('#imageContour').fill('0,0 100,50 0,100');await page.locator('#imageWrap').selectOption('right');await page.locator('#applyObject').click();const image=page.locator('#document-content img');await expect(image).toHaveAttribute('data-image-contour','0,0 100,50 0,100');await expect(image).toHaveCSS('shape-outside',/polygon/);await page.locator('#closePanel').click();await menu(page,'File','export');await page.locator('#htmlExport').click();const downloaded=await download(page,testInfo,'html');await page.locator('#closeDialog').click();await open(page,downloaded);await expect(page.locator('#document-content img')).toHaveAttribute('data-image-contour','0,0 100,50 0,100');await expect(page.locator('#document-content img')).toHaveAttribute('data-image-wrap','right');
});

test('native Word shapes download and reopen as an editable canvas with text intact',async({page},testInfo)=>{
 await start(page);const scene={title:'Native objects',objects:[{id:'text',type:'text',text:'Editable Word café',x:40,y:50,width:400,height:120,group:'word-pair',flipX:true,skewX:15,opacity:60},{id:'oval',type:'ellipse',x:500,y:200,width:200,height:100,group:'word-pair',skewX:20},{id:'pressure',type:'path',x:70,y:380,width:350,height:100,stroke:'#123456',strokeWidth:8,points:[[0,0,.2],[.5,1,.5],[1,.2,1]]},{id:'hidden',type:'text',text:'Do not export this hidden layer',hidden:true}]},file=testInfo.outputPath('native-canvas.html');await fs.writeFile(file,exportHTMLDocument('<div data-forge-design="'+encodeScene(scene)+'"></div>','Native canvas',{}));await open(page,file);await expect(page.locator('#document-content .forge-design')).toHaveCount(1);await menu(page,'File','export');await page.locator('#docxNativeDesigns').check();await page.locator('#docxExport').click();const downloaded=await download(page,testInfo,'docx'),files=unzipSync(new Uint8Array(await fs.readFile(downloaded))),xml=strFromU8(files['word/document.xml']);expect(xml).toContain('wpg:wgp');expect(xml).toContain('Editable Word café');expect(xml).not.toContain('Do not export this hidden layer');expect(files['customXml/slateForgeDesigns.xml']).toBeUndefined();expect(xml).toContain('wpg:grpSp');files['word/document.xml']=strToU8(xml.replace('<w:drawing>','<w:t>Before grouped drawing</w:t><w:drawing>').replace('</w:drawing>','</w:drawing><w:t>After grouped drawing</w:t>'));const mixed=testInfo.outputPath('mixed-native.docx');await fs.writeFile(mixed,zipSync(files));await page.locator('#closeDialog').click();await open(page,mixed);await expect(page.locator('#docCount')).toHaveText('3');await expect(page.locator('#document-content .forge-design > svg')).toContainText('Editable Word café');await expect(page.locator('#document-content .forge-design button')).toContainText('Edit design');await expect(page.locator('#document-content')).toContainText('Before grouped drawing');await expect(page.locator('#document-content')).toContainText('After grouped drawing');await expect(page.locator('#document-content .forge-design path[fill="#123456"]')).toHaveCount(1);expect(await page.locator('#document-content .forge-design [transform*="skewX"]').count()).toBeGreaterThan(0);
});

test('existing simple PDF text edits render, undo and survive actual downloaded PDF export',async({page},testInfo)=>{
 await start(page);const pdf=await PDFDocument.create(),font=await pdf.embedFont(StandardFonts.Helvetica);pdf.addPage([400,400]).drawText('Original editable text',{font,x:40,y:300,size:16});const file=testInfo.outputPath('simple-text.pdf');await fs.writeFile(file,await pdf.save());await menu(page,'Tools','pdfTools');await page.locator('#pdfFile').setInputFiles(file);await expect(page.locator('#pdfStatus')).toContainText('Saved edits');await page.locator('summary').filter({hasText:'Edit existing page text'}).click();await page.locator('#pdfExistingTextValue').fill('Changed existing text');await page.locator('#pdfApplyExistingText').click();await expect(page.locator('#documentToolRoot')).toHaveAttribute('aria-busy','false');await expect(page.locator('#pdfStatus')).toContainText('Saved edits');await expect(page.locator('#pdfExistingTextValue')).toHaveValue('Changed existing text');await page.locator('#pdfUndo').click();await expect(page.locator('#pdfStatus')).toContainText('Saved edits');await expect(page.locator('#pdfExistingTextValue')).toHaveValue('Original editable text');await page.locator('#pdfRedo').click();await expect(page.locator('#pdfStatus')).toContainText('Saved edits');await page.locator('#pdfSave').click();const downloaded=await download(page,testInfo,'pdf'),updated=await loadPDF(new Uint8Array(await fs.readFile(downloaded)));expect(editablePDFText(updated,0).items.map(item=>item.text)).toContain('Changed existing text');expect(editablePDFText(updated,0).items.map(item=>item.text)).not.toContain('Original editable text');
});

test('a downloaded additional PDF signature preserves the original signed revision',async({page},testInfo)=>{
 await start(page);const keys=forge.pki.rsa.generateKeyPair(2048),cert=forge.pki.createCertificate();cert.publicKey=keys.publicKey;cert.serialNumber='01';cert.validity.notBefore=new Date('2020-01-01');cert.validity.notAfter=new Date('2100-01-01');cert.setSubject([{name:'commonName',value:'Ephemeral browser fixture'}]);cert.setIssuer(cert.subject.attributes);cert.sign(keys.privateKey,forge.md.sha256.create());const p12=Uint8Array.from(forge.asn1.toDer(forge.pkcs12.toPkcs12Asn1(keys.privateKey,[cert],'fixture',{algorithm:'3des'})).getBytes(),char=>char.charCodeAt(0)),pdf=await PDFDocument.create();pdf.addPage();const signed=await signPDF(await pdf.save(),p12,'fixture'),source=testInfo.outputPath('first-signed.pdf'),certificate=testInfo.outputPath('ephemeral-fixture.p12');await fs.writeFile(source,signed);await fs.writeFile(certificate,p12);await menu(page,'Tools','pdfTools');await page.locator('#pdfFile').setInputFiles(source);await expect(page.locator('#pdfStatus')).toContainText('Signed PDF');await page.locator('summary').filter({hasText:'Sign the exported PDF with a certificate'}).click();await page.locator('#pdfSigningCertificate').setInputFiles(certificate);await page.locator('#pdfSigningPassword').fill('fixture');await page.locator('#pdfSignAdditional').click();const downloaded=await download(page,testInfo,'pdf'),result=new Uint8Array(await fs.readFile(downloaded));expect(Buffer.from(result.subarray(0,signed.length))).toEqual(Buffer.from(signed));expect((await loadPDF(result)).getForm().getFields().filter(field=>field.constructor.name==='PDFSignature')).toHaveLength(2);await expect(page.locator('#pdfSigningPassword')).toHaveValue('');
});

test('continuous columns keep fitting tables/images on the page and split long content without loss',async({page},testInfo)=>{
 await start(page);const image='data:image/png;base64,'+(await fs.readFile('test/fixtures/ocr-french.png')).toString('base64'),attrs=encodeURIComponent(JSON.stringify({columns:2,orientation:'portrait',pageBreak:false})),wrap=body=>'<section data-forge-section="'+attrs+'"><div data-forge-section-content>'+body+'</div></section>',table='<table><tbody><tr><th>Heading</th><th>Value</th></tr><tr><td>Row</td><td>One</td></tr></tbody></table>',picture='<img src="'+image+'" data-image-width="40">',small=testInfo.outputPath('fitting-columns.html');await fs.writeFile(small,exportHTMLDocument('<p>Before</p>'+wrap('<p>Column text</p>'+table+picture)+'<p>After</p>','Fitting columns',{}));await open(page,small);await menu(page,'View','pagePreview');await expect(page.locator('#printMeasuredPages')).toBeEnabled();await expect(page.locator('.preview-page')).toHaveCount(1);await expect(page.locator('.preview-object-columns table')).toHaveCount(1);await expect(page.locator('.preview-object-columns img')).toHaveCount(1);await page.locator('#closeDialog').click();const text='Every column keeps its café and Unicode 😀 text. '.repeat(250),large=testInfo.outputPath('long-columns.html');await fs.writeFile(large,exportHTMLDocument('<p>Before</p>'+wrap('<p>'+text+'</p>'+table+picture)+'<p>After</p>','Long columns',{}));await open(page,large);await expect(page.locator('#title')).toHaveValue('Long columns');const expected=await page.locator('#document-content').textContent();await menu(page,'View','pagePreview');await expect(page.locator('#printMeasuredPages')).toBeEnabled();expect(await page.locator('.preview-page').count()).toBeGreaterThan(1);expect((await page.locator('.preview-body').allTextContents()).join('')).toBe(expected);const fits=await page.locator('.preview-body,.preview-object-columns').evaluateAll(items=>items.every(item=>item.scrollWidth<=item.clientWidth+2&&item.scrollHeight<=item.clientHeight+2));expect(fits).toBe(true);await expect(page.locator('.preview-scaled-block')).toHaveCount(0);
});

