 await start(page);const nested=encodeURIComponent(JSON.stringify({columns:3,orientation:'portrait',header:'Inner header',pageBreak:false})),attrs=encodeURIComponent(JSON.stringify({columns:2,orientation:'landscape',header:'Wide header',footer:'Wide footer',pageBreak:true})),file=testInfo.outputPath('odt-sections.html');await fs.writeFile(file,exportHTMLDocument('<p>Before section</p><section data-forge-section="'+attrs+'"><div data-forge-section-content><p>Wide first</p><section data-forge-section="'+nested+'"><div data-forge-section-content><p>Inner content</p></div></section><table><tbody><tr><td>Wide table</td></tr></tbody></table><p>Wide last</p></div></section><p>After section</p>','ODT sections',{}));await open(page,file);await expect(page.locator('#document-content .forge-section')).toHaveCount(2);await menu(page,'File','export');await page.locator('#odtExport').click();const downloaded=await download(page,testInfo,'odt'),files=unzipSync(new Uint8Array(await fs.readFile(downloaded)));expect(strFromU8(files['content.xml'])).toContain('<text:section ');expect(strFromU8(files['content.xml'])).toContain('fo:column-count="2"');expect(strFromU8(files['styles.xml'])).toContain('style:print-orientation="landscape"');await page.locator('#closeDialog').click();await open(page,downloaded);await expect(page.locator('#docCount')).toHaveText('3');await expect(page.locator('#document-content .forge-section')).toHaveCount(2);const restored=await page.locator('#document-content .forge-section').first().getAttribute('data-forge-section'),design=JSON.parse(decodeURIComponent(restored));expect(design).toMatchObject({columns:2,orientation:'landscape',header:'Wide header',footer:'Wide footer',pageBreak:true});await expect(page.locator('#document-content .forge-section table')).toContainText('Wide table');await expect(page.locator('#document-content')).toContainText('Before section');await expect(page.locator('#document-content')).toContainText('After section');await menu(page,'View','pagePreview');await expect(page.locator('#printMeasuredPages')).toBeEnabled();const sizes=await page.locator('.preview-page').evaluateAll(items=>items.map(item=>({width:parseFloat(item.style.width),height:parseFloat(item.style.height)})));expect(sizes.some(size=>size.width>size.height)).toBe(true);expect(sizes.some(size=>size.width<size.height)).toBe(true);expect(await page.locator('.preview-header').filter({hasText:'Wide header'}).count()).toBeGreaterThan(0);await expect(page.locator('.preview-header').filter({hasText:'Inner header'})).toHaveCount(1);await expect(page.locator('.preview-body').filter({hasText:'Inner content'})).toHaveCount(1);
