test('workspace and editor meet automated accessibility checks in light and dark palettes',async({page},testInfo)=>{
 test.setTimeout(180000);const findings=[];const audit=async name=>{const result=await new AxeBuilder({page}).withTags(['wcag2a','wcag2aa','wcag21aa','wcag22aa']).analyze();await testInfo.attach(name+'.json',{body:JSON.stringify(result.violations,null,2),contentType:'application/json'});if(result.violations.length)findings.push({screen:name,violations:result.violations.map(v=>({id:v.id,impact:v.impact,nodes:v.nodes.map(n=>({target:n.target,summary:n.failureSummary}))}))})};
 await page.goto('./');await expect(page.locator('#firstVisit')).toBeVisible();await audit('first-visit');await page.locator('[data-next]').click();await audit('palette-setup');await page.locator('[data-skip]').click();await page.locator('#backstageToggle').click();await audit('workspace-light');await page.locator('#continueWriting').click();
 for(const theme of ['white','linen','mist','sage','grey','colored','dark','midnight','plum','forest','system']){await menu(page,'View','appearance');if(theme==='white')await audit('preferences');await page.locator('#uiTheme').selectOption(theme);await page.locator('#closeDialog').click();await audit('editor-'+theme)}
 await page.locator('#backstageToggle').click();await audit('workspace-final');expect(findings).toEqual([]);
});

test('saved writing survives repeated reloads while another tab gets its own workspace',async({page,context})=>{
 test.setTimeout(180000);await start(page);await write(page);const workspace=()=>page.evaluate(()=>JSON.parse(sessionStorage.getItem('document-studio.session.v1')).id),id=await workspace();
 for(let pass=0;pass<6;pass++){await page.reload();await expect(page.locator('#title')).toHaveValue('Release smoke document');await enterEditor(page);await expect(page.locator('#document-content')).toContainText('An independent backup keeps this document safe.');await expect(page.locator('#saveState')).toHaveText('Saved on this device');expect(await workspace()).toBe(id)}
 const other=await context.newPage(),errors=[];other.on('pageerror',error=>errors.push(error.message));try{await start(other);await expect(other.locator('#title')).toHaveValue('Untitled document');expect(await other.evaluate(()=>JSON.parse(sessionStorage.getItem('document-studio.session.v1')).id)).not.toBe(id);await expect(page.locator('#title')).toHaveValue('Release smoke document');expect(await workspace()).toBe(id);expect(errors).toEqual([])}finally{await other.close()}
 await page.reload();await expect(page.locator('#title')).toHaveValue('Release smoke document');await enterEditor(page);await expect(page.locator('#document-content')).toContainText('An independent backup keeps this document safe.');expect(await workspace()).toBe(id);
});

test('a new release applies silently on launch and keeps writing in both tabs',async({page,context},testInfo)=>{
 test.setTimeout(180000);
 const directory='update-fixture-'+testInfo.project.name,root='dist/'+directory,base='./'+directory+'/',worker=await fs.readFile('dist/sw.js','utf8'),html=await fs.readFile('dist/index.html','utf8'),app=await fs.readFile('dist/app.js','utf8');
 await fs.mkdir(root,{recursive:true});let other;
 const publish=async(version,hash)=>{await fs.writeFile(root+'/app.js',app+'\ndocument.body.dataset.testRelease='+JSON.stringify(version)+';');await fs.writeFile(root+'/index.html',html);await fs.writeFile(root+'/sw.js',worker.replace(/const CACHE=PREFIX\+'[a-f0-9]{16}'/,"const CACHE=PREFIX+'"+hash+"'"))};
 try{
  for(const entry of await fs.readdir('dist',{withFileTypes:true}))if(!entry.name.startsWith('update-fixture-')&&!['vendor','index.html','sw.js','app.js'].includes(entry.name))await fs.cp('dist/'+entry.name,root+'/'+entry.name,{recursive:true});
  await publish('A','1111111111111111');await page.goto(base);await expect(page.locator('#document-content')).toBeAttached();await enterEditor(page);await write(page);await page.evaluate(()=>navigator.serviceWorker.ready);await page.waitForFunction(()=>!!navigator.serviceWorker.controller);
  const identity=await page.evaluate(()=>JSON.parse(sessionStorage.getItem('document-studio.session.v1')).id);
  other=await context.newPage();const errors=[];other.on('pageerror',error=>errors.push(error.message));await other.goto(base);await expect(other.locator('#document-content')).toBeAttached();await enterEditor(other);await other.locator('#title').fill('Other tab document');await other.locator('#document-content').fill('Other tab writing stays intact.');await menu(other,'File','saveNow');await expect(other.locator('#toast')).toHaveText('Workspace saved on this device.');
  await publish('B','2222222222222222');await page.reload();await expect(page.locator('body')).toHaveAttribute('data-test-release','B',{timeout:60000});await expect(page.locator('#title')).toHaveValue('Release smoke document');await enterEditor(page);await expect(page.locator('#document-content')).toContainText('An independent backup');expect(await page.evaluate(()=>JSON.parse(sessionStorage.getItem('document-studio.session.v1')).id)).toBe(identity);
  await expect(other.locator('body')).toHaveAttribute('data-test-release','B',{timeout:60000});await expect(other.locator('#title')).toHaveValue('Other tab document');await enterEditor(other);await expect(other.locator('#document-content')).toContainText('Other tab writing stays intact.');expect(errors).toEqual([]);await expect(page.locator('[data-menu-action=updateApp]')).toHaveCount(0);
  await context.setOffline(true);await page.reload();await expect(page.locator('body')).toHaveAttribute('data-test-release','B');await expect(page.locator('#title')).toHaveValue('Release smoke document');await enterEditor(page);await expect(page.locator('#document-content')).toContainText('An independent backup');
 }finally{await other?.close();await context.close();await fs.rm(root,{recursive:true,force:true})}
});

test('native ODT pictures download with editable crop and current image edits survive device reload',async({page},testInfo)=>{
 await start(page);const png='data:image/png;base64,'+(await fs.readFile('test/fixtures/odt-pictures/quadrants.png')).toString('base64'),scene=encodeScene({title:'Native picture canvas',objects:[{type:'image',src:png,aspectRatio:1.5,x:40,y:40,width:300,height:200,zoom:150,cropX:25,cropY:70,flipX:true,opacity:70},{type:'text',text:'Hidden picture secret',hidden:true}]}),file=testInfo.outputPath('pictures.html');await fs.writeFile(file,exportHTMLDocument('<p>Before pictures</p><div data-forge-design="'+scene+'"></div><p>After pictures</p>','Native pictures',{}));await open(page,file);await menu(page,'File','export');await page.locator('#odtNativeDesigns').check();await expect(page.locator('#dialog')).toContainText('cropped-out pixels');await page.locator('#odtExport').click();const downloaded=await download(page,testInfo,'odt'),files=unzipSync(new Uint8Array(await fs.readFile(downloaded))),xml=strFromU8(files['content.xml']);expect(xml).toContain('<draw:image');expect(xml).toContain('fo:clip="rect(');expect(xml).not.toContain('Hidden picture secret');expect(Object.keys(files).some(n=>n.startsWith('SlateForge/'))).toBe(false);await page.locator('#closeDialog').click();files['content.xml']=strToU8(xml.replace('draw:image-opacity="70%"','draw:image-opacity="45%"'));const edited=testInfo.outputPath('pictures-edited.odt');await fs.writeFile(edited,zipSync(files));await open(page,edited);await expect(page.getByRole('button',{name:'Edit design canvas: Native picture canvas',exact:true})).toBeVisible();await menu(page,'File','saveNow');await expect(page.locator('#saveState')).toHaveText('Saved on this device');await page.reload();await enterEditor(page);await menu(page,'File','export');await page.locator('#htmlExport').click();const html=await download(page,testInfo,'html'),source=await fs.readFile(html,'utf8');expect(source).toContain(encodeURIComponent('"opacity":45'));expect(source).not.toContain(encodeURIComponent('Hidden picture secret'));await page.locator('#closeDialog').click();await open(page,'test/fixtures/odt-pictures-libreoffice-resaved.odt');await expect(page.getByRole('button',{name:'Edit design canvas: Native pictures',exact:true})).toBeVisible();
});
